import random
random.seed(0)
# 동기식 데이터 병렬: 한 스텝은 '가장 늦은 일꾼' 이 끝나야 끝난다
def step_time(n):
    # 일꾼마다 기본 1.0초 + 가끔 생기는 지연(평균 0.02초, 지수분포)
    return max(1.0 + random.expovariate(1 / 0.02) for _ in range(n))
for n in (1, 8, 64, 1024, 16384):
    avg = sum(step_time(n) for _ in range(200)) / 200
    print(f"workers={n:6d}  mean step={avg:.3f}s  efficiency={1/avg:.1%}")
